package ch.bbw.zork;/** * Stellt einen Befehl im Zork-Spiel dar. * Ein Befehl besteht aus einem Befehlswort und * kann zusätzlich ein zweites Wort enthalten. */public class Command {	private String commandWord;	private String secondWord;	/**	 * Erstellt einen Befehl mit einem Befehlswort.	 *	 * @param commandWord Befehlswort	 */	public Command(String commandWord) {		this(commandWord, null);	}	/**	 * Erstellt einen Befehl mit einem Befehlswort und einem zweiten Wort.	 *	 * @param commandWord Befehlswort	 * @param secondWord zweites Wort des Befehls	 */	public Command(String commandWord, String secondWord) {		this.commandWord = commandWord;		this.secondWord = secondWord;	}	/**	 * Gibt das Befehlswort zurück.	 *	 * @return Befehlswort	 */	public String getCommandWord() {		return commandWord;	}	/**	 * Gibt das zweite Wort zurück.	 *	 * @return zweites Wort	 */	public String getSecondWord() {		return secondWord;	}	/**	 * Prüft, ob der Befehl unbekannt ist.	 *	 * @return true, wenn der Befehl unbekannt ist	 */	public boolean isUnknown() {		return commandWord == null;	}	/**	 * Prüft, ob der Befehl ein zweites Wort besitzt.	 *	 * @return true, wenn ein zweites Wort vorhanden ist	 */	public boolean hasSecondWord() {		return secondWord != null;	}}